-- =====================================================================
-- Waterdrop — customer accounts (Home / Store / Company), branches,
-- family & team members, supplier search with approval, combined bills.
--
-- GENERATED by scripts/gen-migration-12.py (do not edit by hand).
--
-- A "branch" is an existing customers row (stock, orders, deliveries and
-- billing already work per row). A customer account groups branches and
-- members. Roles: owner (everything), admin (everything but the owner),
-- member (order, confirm deliveries, record usage — no bills/payments).
-- Branches of one account served by the same supplier bill to a head
-- branch, so the account gets one combined bill per supplier.
-- =====================================================================

create type public.customer_account_type as enum ('home', 'store', 'company');
create type public.account_member_role as enum ('owner', 'admin', 'member');

create table public.customer_accounts (
  id uuid primary key default gen_random_uuid(),
  name text not null check (char_length(name) between 2 and 120),
  account_type public.customer_account_type not null default 'home',
  owner_id uuid not null references public.profiles (id) on delete cascade,
  created_at timestamptz not null default now()
);
create index customer_accounts_owner_idx on public.customer_accounts (owner_id);

create table public.customer_account_members (
  id uuid primary key default gen_random_uuid(),
  account_id uuid not null references public.customer_accounts (id) on delete cascade,
  user_id uuid not null references public.profiles (id) on delete cascade,
  role public.account_member_role not null default 'member',
  status text not null default 'active' check (status in ('active', 'blocked')),
  all_branches boolean not null default true,
  blocked_at timestamptz,
  created_at timestamptz not null default now(),
  constraint customer_account_members_uq unique (account_id, user_id)
);
create index customer_account_members_user_idx on public.customer_account_members (user_id);

create table public.customer_member_branches (
  member_id uuid not null references public.customer_account_members (id) on delete cascade,
  customer_id uuid not null references public.customers (id) on delete cascade,
  primary key (member_id, customer_id)
);

create table public.customer_member_invites (
  id uuid primary key default gen_random_uuid(),
  account_id uuid not null references public.customer_accounts (id) on delete cascade,
  code text not null unique check (code ~ '^[A-Z0-9]{8}$'),
  role public.account_member_role not null check (role <> 'owner'),
  all_branches boolean not null default true,
  branch_ids uuid[] not null default '{}',
  label text check (label is null or char_length(label) <= 80),
  expires_at timestamptz not null default now() + interval '7 days',
  used_by uuid references public.profiles (id),
  used_at timestamptz,
  revoked_at timestamptz,
  created_by uuid references public.profiles (id),
  created_at timestamptz not null default now()
);
create index customer_member_invites_account_idx on public.customer_member_invites (account_id);

alter table public.customers
  add column account_id uuid references public.customer_accounts (id) on delete set null,
  add column branch_name text check (branch_name is null or char_length(branch_name) between 1 and 80),
  add column bill_to_customer_id uuid references public.customers (id) on delete set null;
create index customers_account_idx on public.customers (account_id);
create index customers_bill_to_idx on public.customers (bill_to_customer_id) where bill_to_customer_id is not null;
-- An account may have several branches with the same supplier.
drop index if exists public.customers_user_supplier_uq;

alter table public.suppliers add column listed boolean not null default true;

create table public.supplier_connection_requests (
  id uuid primary key default gen_random_uuid(),
  account_id uuid not null references public.customer_accounts (id) on delete cascade,
  supplier_id uuid not null references public.suppliers (id) on delete cascade,
  branch_name text check (branch_name is null or char_length(branch_name) between 1 and 80),
  contact_name text not null check (char_length(contact_name) between 2 and 120),
  phone text check (phone is null or phone ~ '^\+?[0-9 ]{7,16}$'),
  address text not null check (char_length(address) between 3 and 500),
  delivery_instructions text check (delivery_instructions is null or char_length(delivery_instructions) <= 500),
  household_type text check (household_type in ('single', 'couple', 'family', 'shared_room', 'office', 'shop', 'other')),
  members_count integer check (members_count between 1 and 500),
  opening_stock integer check (opening_stock between 0 and 1000),
  daily_consumption integer not null default 0 check (daily_consumption between 0 and 1000),
  status text not null default 'pending' check (status in ('pending', 'approved', 'rejected', 'cancelled')),
  reason text check (reason is null or char_length(reason) <= 300),
  customer_id uuid references public.customers (id) on delete set null,
  requested_by uuid references public.profiles (id),
  decided_by uuid references public.profiles (id),
  decided_at timestamptz,
  created_at timestamptz not null default now()
);
create index supplier_connection_requests_supplier_idx on public.supplier_connection_requests (supplier_id, status);
create unique index supplier_connection_requests_pending_uq
  on public.supplier_connection_requests (account_id, supplier_id, lower(address)) where status = 'pending';

-- ---------------------------------------------------------------------
-- Backfill: one account per existing app customer; they become owner.
-- ---------------------------------------------------------------------
insert into public.customer_accounts (name, account_type, owner_id, created_at)
select (array_agg(c.customer_name order by c.created_at))[1],
       case when bool_or(c.household_type = 'shop') then 'store'::public.customer_account_type
            when bool_or(c.household_type = 'office') then 'company'::public.customer_account_type
            else 'home'::public.customer_account_type end,
       c.user_id, min(c.created_at)
from public.customers c
where c.user_id is not null
group by c.user_id;

update public.customers c set account_id = a.id
from public.customer_accounts a where a.owner_id = c.user_id and c.account_id is null;

insert into public.customer_account_members (account_id, user_id, role, created_at)
select id, owner_id, 'owner', created_at from public.customer_accounts
on conflict (account_id, user_id) do nothing;

-- ---------------------------------------------------------------------
-- Access helpers
-- ---------------------------------------------------------------------
create or replace function public.head_customer_id(p_customer_id uuid) returns uuid
language sql stable security definer set search_path = public as $$
  select coalesce(bill_to_customer_id, id) from public.customers where id = p_customer_id;
$$;

-- The head branch plus every branch that bills to it.
create or replace function public.billing_group(p_head uuid) returns setof uuid
language sql stable security definer set search_path = public as $$
  select id from public.customers where id = p_head or bill_to_customer_id = p_head;
$$;

create or replace function public.my_customer_ids() returns setof uuid
language sql stable security definer set search_path = public as $$
  select c.id from public.customers c
  where c.account_id is null and c.user_id = auth.uid()
  union
  select c.id from public.customers c
  join public.customer_account_members m on m.account_id = c.account_id
  where m.user_id = auth.uid() and m.status = 'active'
    and (m.all_branches or m.role in ('owner', 'admin')
         or exists (select 1 from public.customer_member_branches b where b.member_id = m.id and b.customer_id = c.id));
$$;

-- Branches whose bills and payments the caller may see (owner / admin).
create or replace function public.my_billing_customer_ids() returns setof uuid
language sql stable security definer set search_path = public as $$
  select c.id from public.customers c
  where c.account_id is null and c.user_id = auth.uid()
  union
  select c.id from public.customers c
  join public.customer_account_members m on m.account_id = c.account_id
  where m.user_id = auth.uid() and m.status = 'active' and m.role in ('owner', 'admin');
$$;

create or replace function public.my_account_ids() returns setof uuid
language sql stable security definer set search_path = public as $$
  select account_id from public.customer_account_members where user_id = auth.uid() and status = 'active';
$$;

create or replace function public.my_account_role(p_account_id uuid) returns text
language sql stable security definer set search_path = public as $$
  select role::text from public.customer_account_members
  where account_id = p_account_id and user_id = auth.uid() and status = 'active';
$$;

create or replace function public.require_account_admin(p_account_id uuid) returns void
language plpgsql stable security definer set search_path = public as $$
begin
  perform public.require_auth();
  if coalesce(public.my_account_role(p_account_id), '') not in ('owner', 'admin') then
    raise exception 'Only the account owner or an admin can do this' using errcode = '42501';
  end if;
end $$;

-- Owner/admin only: money actions on a branch (resolved by the caller to the head branch).
create or replace function public.customer_for_billing(p_customer_id uuid) returns public.customers
language plpgsql stable security definer set search_path = public as $$
declare
  c public.customers;
begin
  perform public.require_auth();
  select * into c from public.customers where id = p_customer_id;
  if c.id is null then
    raise exception 'Customer not found' using errcode = 'P0002';
  end if;
  if c.id not in (select public.my_billing_customer_ids()) then
    raise exception 'Only the account owner or an admin can handle bills and payments' using errcode = '42501';
  end if;
  if c.blocked_at is not null then
    raise exception 'This account has been blocked by your supplier. Please contact them.' using errcode = '42501';
  end if;
  return c;
end $$;

-- Sends a notification to every active member with access to the branch
-- ('billing' audience: owner and admins only). Returns one inserted id.
create or replace function public.notify_customer(
  p_customer_id uuid, p_audience text, p_type text, p_severity text, p_title text, p_message text,
  p_link text default null, p_data jsonb default '{}'::jsonb, p_dedupe_key text default null
) returns uuid
language plpgsql security definer set search_path = public as $$
declare
  c public.customers;
  r record;
  v_id uuid;
  v_first uuid;
begin
  select * into c from public.customers where id = p_customer_id;
  if c.id is null then
    return null;
  end if;
  if c.account_id is null then
    return public.notify(c.user_id, p_type, p_severity, p_title, p_message, p_link, p_data, p_dedupe_key);
  end if;
  for r in
    select m.user_id from public.customer_account_members m
    where m.account_id = c.account_id and m.status = 'active'
      and (case when p_audience = 'billing' then m.role in ('owner', 'admin')
                else m.all_branches or m.role in ('owner', 'admin')
                     or exists (select 1 from public.customer_member_branches b where b.member_id = m.id and b.customer_id = c.id)
           end)
  loop
    v_id := public.notify(r.user_id, p_type, p_severity, p_title, p_message, p_link, p_data,
                          case when p_dedupe_key is null then null else p_dedupe_key || ':' || r.user_id end);
    v_first := coalesce(v_first, v_id);
  end loop;
  return v_first;
end $$;

-- Creates a branch (customers row) for an account at a supplier. Internal.
create or replace function public.create_branch(
  p_account_id uuid, p_supplier_id uuid, p_branch_name text, p_contact_name text, p_phone text, p_address text,
  p_instructions text, p_household_type text, p_members_count integer, p_opening_stock integer,
  p_daily_consumption integer, p_actor uuid
) returns public.customers
language plpgsql security definer set search_path = public as $$
declare
  a public.customer_accounts;
  v_settings public.supplier_settings;
  v_owner uuid;
  v_head uuid;
  c public.customers;
begin
  select * into a from public.customer_accounts where id = p_account_id;
  select * into v_settings from public.supplier_settings where supplier_id = p_supplier_id;
  select owner_id into v_owner from public.suppliers where id = p_supplier_id;
  if p_opening_stock is not null and (p_opening_stock < 0 or p_opening_stock > 1000) then
    raise exception 'Opening stock must be between 0 and 1000 cans' using errcode = '22023';
  end if;
  if exists (select 1 from public.customers where account_id = p_account_id and supplier_id = p_supplier_id
             and lower(address) = lower(trim(p_address))) then
    raise exception 'This address is already connected to this supplier' using errcode = '23505';
  end if;
  -- One combined bill per account per supplier: later branches bill to the first.
  select id into v_head from public.customers
  where account_id = p_account_id and supplier_id = p_supplier_id and bill_to_customer_id is null
  order by created_at limit 1;

  insert into public.customers (user_id, supplier_id, account_id, branch_name, bill_to_customer_id, customer_name, phone,
                                address, delivery_instructions, daily_consumption, low_stock_threshold, critical_threshold,
                                safety_stock, household_type, members_count)
  values (a.owner_id, p_supplier_id, p_account_id, nullif(trim(coalesce(p_branch_name, '')), ''), v_head,
          trim(p_contact_name), nullif(trim(coalesce(p_phone, '')), ''), trim(p_address),
          nullif(trim(coalesce(p_instructions, '')), ''), coalesce(p_daily_consumption, 0),
          greatest(v_settings.default_low_stock_threshold, v_settings.default_critical_threshold),
          v_settings.default_critical_threshold, v_settings.default_safety_stock, p_household_type, p_members_count)
  returning * into c;
  insert into public.customer_stock (customer_id, supplier_id) values (c.id, c.supplier_id);
  if p_opening_stock is not null then
    insert into public.inventory_transactions (supplier_id, customer_id, transaction_type, quantity, reference_type,
                                               transaction_date, idempotency_key, created_by, notes)
    values (c.supplier_id, c.id, 'opening_stock', p_opening_stock, 'manual', public.customer_local_date(c.id),
            'opening:' || c.id, p_actor, 'Opening stock entered at registration');
  end if;
  perform public.notify(v_owner, 'account', 'info', 'New customer connected',
    format('%s%s joined your delivery list.', a.name, coalesce(' – ' || c.branch_name, '')),
    '/supplier/customers/' || c.id, jsonb_build_object('customer_id', c.id));
  perform public.write_audit('customer.connected', 'customer', c.id, c.supplier_id,
    jsonb_build_object('account_id', p_account_id, 'branch', c.branch_name, 'combined_bill_with', v_head));
  return c;
end $$;

-- ---------------------------------------------------------------------
-- Row Level Security for the new tables + policies that used user_id
-- ---------------------------------------------------------------------
alter table public.customer_accounts enable row level security;
alter table public.customer_account_members enable row level security;
alter table public.customer_member_branches enable row level security;
alter table public.customer_member_invites enable row level security;
alter table public.supplier_connection_requests enable row level security;

create policy accounts_select on public.customer_accounts for select to authenticated using (
  id in (select public.my_account_ids())
  or id in (select account_id from public.customers where supplier_id = public.my_supplier_id())
  or id in (select account_id from public.supplier_connection_requests where supplier_id = public.my_supplier_id())
  or public.is_admin()
);
create policy account_members_select on public.customer_account_members for select to authenticated using (
  user_id = auth.uid() or account_id in (select public.my_account_ids()) or public.is_admin()
);
create policy member_branches_select on public.customer_member_branches for select to authenticated using (
  member_id in (select id from public.customer_account_members where account_id in (select public.my_account_ids()))
  or public.is_admin()
);
create policy member_invites_select on public.customer_member_invites for select to authenticated using (
  public.my_account_role(account_id) in ('owner', 'admin') or public.is_admin()
);
create policy connection_requests_select on public.supplier_connection_requests for select to authenticated using (
  account_id in (select public.my_account_ids()) or supplier_id = public.my_supplier_id() or public.is_admin()
);
revoke insert, update, delete on public.customer_accounts, public.customer_account_members, public.customer_member_branches,
  public.customer_member_invites, public.supplier_connection_requests from authenticated;
revoke all on public.customer_accounts, public.customer_account_members, public.customer_member_branches,
  public.customer_member_invites, public.supplier_connection_requests from anon;

drop policy customers_select on public.customers;
create policy customers_select on public.customers for select to authenticated using (
  id in (select public.my_customer_ids()) or supplier_id = public.my_supplier_id() or public.is_admin()
);

drop policy suppliers_select on public.suppliers;
create policy suppliers_select on public.suppliers for select to authenticated using (
  owner_id = auth.uid()
  or id = public.my_supplier_id()
  or public.is_admin()
  or id in (select supplier_id from public.customers where id in (select public.my_customer_ids()))
  or id in (select supplier_id from public.supplier_connection_requests where account_id in (select public.my_account_ids()))
);

drop policy supplier_settings_select on public.supplier_settings;
create policy supplier_settings_select on public.supplier_settings for select to authenticated using (
  supplier_id = public.my_supplier_id()
  or public.is_admin()
  or supplier_id in (select supplier_id from public.customers where id in (select public.my_customer_ids()))
);

drop policy profiles_select on public.profiles;
create policy profiles_select on public.profiles for select to authenticated using (
  id = auth.uid()
  or public.is_admin()
  or id in (select user_id from public.customers where supplier_id = public.my_supplier_id())
  or id in (select user_id from public.supplier_staff where supplier_id = public.my_manager_supplier_id())
  or id in (select s.owner_id from public.suppliers s join public.customers c on c.supplier_id = s.id
            where c.id in (select public.my_customer_ids()))
  or id in (select user_id from public.customer_account_members where account_id in (select public.my_account_ids()))
);

-- Money: family/team Members do not see bills or payments.
do $$
declare t text;
begin
  foreach t in array array['invoices', 'credit_notes', 'payments'] loop
    execute format('drop policy %1$s_select on public.%1$I', t);
    execute format($f$
      create policy %1$s_select on public.%1$I for select to authenticated using (
        supplier_id = public.my_manager_supplier_id()
        or customer_id in (select public.my_billing_customer_ids())
        or public.is_admin()
      )$f$, t);
  end loop;
end $$;
